"use client";
import * as React from "react";
import { cn } from "./utils";
import { Button, type ButtonProps } from "./button";
export function IconButton({
  label,
  children,
  size = "md",
  className,
  ...props
}: Omit<ButtonProps, "asChild"> & { label: string }) {
  return (
    <Button
      aria-label={label}
      size={size}
