import { Slider as Primitive } from "radix-ui";
export function Slider({
  className,
  label = "Value",
  ...props
}: React.ComponentProps<typeof Primitive.Root> & { label?: string }) {
  return (
    <Primitive.Root
      defaultValue={[50]}
      className={cn(
        "relative flex h-8 w-full touch-none select-none items-center",
