  ref: forwardedRef,
  ...rootProps
}: WebGLProps & { kind: SceneKind }) {
  const colors = {
    silk: "#b7cdbb",
    eclipse: "#edbd79",
    tunnel: "#a6bce4",
    constellation: "#a6d0c0",
    particles: "#b9a4f8",
    ribbons: "#8daed1",
    liquid: "#737fd7",
    orb: "#eab89d",
    terrain: "#b2c08b",
    "terrain-relief": "#b2c08b",
    distortion: "#d7dfcf",
  };
  const backgrounds = {
    silk: "#030405",
    eclipse: "#030405",
    tunnel: "#030405",
    constellation: "#030405",
    particles: "#10101c",
    ribbons: "#10151d",
    liquid: "#1c2945",
    orb: "#241c2b",
    terrain: "#14221e",
    "terrain-relief": "#14221e",
    distortion: "#d7dfcf",
  };
  const color = suppliedColor ?? colors[kind];
  const ref = React.useRef<HTMLDivElement>(null);
  const [visible, setVisible] = React.useState(false);
  const [ready, setReady] = React.useState(false);
  const [lost, setLost] = React.useState(false);
  const [reduce, setReduce] = React.useState(true);
  React.useEffect(() => {
    const media = matchMedia("(prefers-reduced-motion: reduce)");
    const change = () => setReduce(media.matches);
    change();
    media.addEventListener("change", change);
