                return (
                  <g key={i}>
                    <line
                      x1={x}
                      y1={y}
                      x2={300 + Math.sin((i + 1) * 19.1) * 240}
                      y2={200 + Math.cos((i + 1) * 7.7) * 160}
                      stroke={color}
                      opacity=".15"
                    />
                    <circle cx={x} cy={y} r="2" fill={color} />
                  </g>
                );
              })}
            </>
          ) : kind === "orb" ? (
            <>
              <defs>
                <radialGradient id="jez-orb-poster" cx="30%" cy="22%">
