          material.uniforms.picture.value = t;
          material.uniforms.imageAspect.value = t.image.width / t.image.height;
          invalidate();
        },
        undefined,
        () => {
          invalidate();
        },
      );
    return () => {
      cancelled = true;
      texture.dispose();
    };
  }, [kind, imageSrc, text, material, invalidate]);
