    <mesh
      ref={ref}
      material={material}
      rotation={kind === "terrain-relief" ? [-0.75, 0, 0] : [0, 0, 0]}
    >
      {kind === "terrain-relief" ? (
        <planeGeometry
          args={[
            Math.max(14, (size.width / Math.max(size.height, 1)) * 7),
            10,
            280,
            180,
          ]}
        />
      ) : (
        <planeGeometry args={[2, 2]} />
      )}
