    () =>
      new THREE.ShaderMaterial({
        vertexShader: kind === "terrain-relief" ? terrainVertex : screenVertex,
        fragmentShader:
          kind === "orb"
            ? orbFragment
            : kind === "liquid"
              ? liquidFragment
              : kind === "terrain-relief"
                ? terrainReliefFragment
