          >
            <WebGLScene
              kind={kind}
              color={color}
              speed={speed}
              text={text}
              imageSrc={imageSrc}
              composition={composition}
            />
          </Canvas>
        </Boundary>
      ) : (
        fallback
      )}
    </div>
  );
}

"use client";
import * as React from "react";
import { useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";
import { RibbonScene } from "./webgl-ribbons";
import {
  screenVertex,
  orbFragment,
  liquidFragment,
  distortionFragment,
  terrainFragment,
  terrainVertex,
  terrainReliefFragment,
  particleVertex,
  particleFragment,
} from "./webgl-shaders";
import { AtmosphereScene } from "./webgl-atmospheres";
export type SceneKind =
  | "silk"
  | "eclipse"
  | "tunnel"
  | "constellation"
  | "particles"
  | "ribbons"
  | "liquid"
  | "orb"
  | "terrain-relief"
  | "terrain"
  | "distortion";
export type SceneProps = {
  kind: SceneKind;
  color: string;
  speed: number;
  text?: string;
  imageSrc?: string;
  composition?: "fold" | "orbit";
