col+=tint*exp(-d*65.)*(.09+sparkle*.16)*depth;
if(sparkle>.5){vec2 star=abs(p-q);col+=tint*.25*sparkle*exp(-min(star.x,star.y)*550.-max(star.x,star.y)*85.);}
