                    <line
                      x1={x}
                      y1={y}
                      x2={300 + Math.sin((i + 1) * 19.1) * 240}
                      y2={200 + Math.cos((i + 1) * 7.7) * 160}
                      stroke={color}
                      opacity=".15"
