        </svg>
      )}
    </div>
  );
  React.useImperativeHandle(forwardedRef, () => ref.current!, []);
  return (
    <div
      {...rootProps}
      ref={ref}
      role="img"
      aria-label={label}
      style={{ background: backgrounds[kind], ...rootProps.style }}
      className={cn(
        "relative h-[400px] w-full overflow-hidden rounded-xl",
        className,
      )}
    >
      {ready && !lost && !reduce && visible ? (
        <Boundary fallback={fallback}>
          <Canvas
            dpr={[1, 1.5]}
            frameloop={paused ? "demand" : "always"}
            camera={{ position: [0, 0, 5], fov: 48 }}
            gl={{ antialias: true, alpha: true, powerPreference: "low-power" }}
            onCreated={({ gl }) => {
              gl.domElement.addEventListener(
                "webglcontextlost",
                () => setLost(true),
                { once: true },
              );
            }}
          >
            <WebGLScene
              kind={kind}
              color={color}
              speed={speed}
              text={text}
              imageSrc={imageSrc}
              composition={composition}
            />
          </Canvas>
        </Boundary>
      ) : (
        fallback
      )}
    </div>
  );
}

"use client";
import * as React from "react";
import { useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";
import { RibbonScene } from "./webgl-ribbons";
import {
  screenVertex,
  orbFragment,
  liquidFragment,
  distortionFragment,
  terrainFragment,
  terrainVertex,
  terrainReliefFragment,
  particleVertex,
  particleFragment,
} from "./webgl-shaders";
import { AtmosphereScene } from "./webgl-atmospheres";
export type SceneKind =
  | "silk"
  | "eclipse"
  | "tunnel"
  | "constellation"
  | "particles"
  | "ribbons"
  | "liquid"
  | "orb"
  | "terrain-relief"
  | "terrain"
  | "distortion";
export type SceneProps = {
  kind: SceneKind;
  color: string;
  speed: number;
  text?: string;
  imageSrc?: string;
  composition?: "fold" | "orbit";
