    () => () => {
      geometry.dispose();
      material.dispose();
    },
    [geometry, material],
  );
  useFrame(({ pointer }, d) => {
    material.uniforms.time.value += Math.min(d, 0.05) * speed;
    material.uniforms.pointer.value.lerp(pointer, 0.04);
  });
  return (
    <points
      geometry={geometry}
      material={material}
      rotation={[0.18, 0, -0.25]}
    />
  );
}
function Surface({ kind, color, speed, imageSrc, text = "FORM" }: SceneProps) {
