              kind={kind}
              color={color}
              speed={speed}
              text={text}
              imageSrc={imageSrc}
              composition={composition}
            />
          </Canvas>
        </Boundary>
      ) : (
        fallback
      )}
    </div>
  );
}

"use client";
import * as React from "react";
import { useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";
import { RibbonScene } from "./webgl-ribbons";
import {
  screenVertex,
  orbFragment,
  liquidFragment,
  distortionFragment,
  terrainFragment,
  terrainVertex,
  terrainReliefFragment,
  particleVertex,
  particleFragment,
} from "./webgl-shaders";
import { AtmosphereScene } from "./webgl-atmospheres";
export type SceneKind =
  | "silk"
  | "eclipse"
  | "tunnel"
  | "constellation"
  | "particles"
  | "ribbons"
  | "liquid"
  | "orb"
  | "terrain-relief"
  | "terrain"
  | "distortion";
export type SceneProps = {
  kind: SceneKind;
  color: string;
  speed: number;
  text?: string;
  imageSrc?: string;
  composition?: "fold" | "orbit";
};
function Field({ color, speed }: { color: string; speed: number }) {
  const material = React.useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: particleVertex,
        fragmentShader: particleFragment,
        uniforms: {
          time: { value: 0 },
          pointer: { value: new THREE.Vector2() },
          tint: { value: new THREE.Color(color) },
        },
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    [color],
  );
  const geometry = React.useMemo(() => {
    const n = 18000,
      p = new Float32Array(n * 3),
      s = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      const a = i * 2.39996323;
      const r = 0.7 + Math.pow((i + 0.5) / n, 0.7) * 1.6;
      const warp = Math.sin(a * 3) * 0.18;
      const seed = (Math.sin(i * 127.1) * 43758.5453) % 1;
      const scatter = Math.abs(seed);
      p[i * 3] = Math.cos(a) * r;
      p[i * 3 + 1] = Math.sin(a) * r * 0.6 + Math.sin(r * 3) * 0.12;
      p[i * 3 + 2] =
        Math.sin(a * 2 + r * 3) * 0.42 + warp + (scatter - 0.5) * 0.12;
      s[i] = scatter;
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.BufferAttribute(p, 3));
    g.setAttribute("seed", new THREE.BufferAttribute(s, 1));
    return g;
  }, []);
