    <div
      {...rootProps}
      ref={ref}
      role="img"
      aria-label={label}
      style={{ background: backgrounds[kind], ...rootProps.style }}
      className={cn(
        "relative h-[400px] w-full overflow-hidden rounded-xl",
        className,
      )}
    >
      {ready && !lost && !reduce && visible ? (
        <Boundary fallback={fallback}>
          <Canvas
            dpr={[1, 1.5]}
