      const a = i * 2.39996323;
      const r = 0.7 + Math.pow((i + 0.5) / n, 0.7) * 1.6;
      const warp = Math.sin(a * 3) * 0.18;
      const seed = (Math.sin(i * 127.1) * 43758.5453) % 1;
      const scatter = Math.abs(seed);
      p[i * 3] = Math.cos(a) * r;
      p[i * 3 + 1] = Math.sin(a) * r * 0.6 + Math.sin(r * 3) * 0.12;
